INSERT INTO `wp_posts` VALUES (61,1,'2025-09-23 21:25:02','2025-09-23 21:25:02','<!-- wp:paragraph -->\n<p><a href=\"../index.html\">Home </a>. Become a partner</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"../wp-content/themes/brainlab/public/image/partner/wave-bg.webp\" alt=\"Become a partner- image 1\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image -->\n<figure class=\"wp-block-image\"><img src=\"../wp-content/themes/brainlab/public/image/partner/circle-bg-1.webp\" alt=\"Стати партнером- image 2\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading {\"level\":1} -->\n<h1 class=\"wp-block-heading\">Become a partner</h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Are you interested in joining the partner program?<br>Sign up and our partner team will reach out to you.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We offer our professional and certified technical support at each stage of project implementation, training, technical consultation, information and marketing support.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><a href=\"tel:+92 (333) 1234567\">+92 333 1234567</a><a href=\"../cdn-cgi/l/email-protection.html#e59684898096cb9084a58c8c9181cb9084\">info@Cyberxs.net</a></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Vendors</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">“Empowering&nbsp;partners&nbsp;to grow, differentiate, and succeed&nbsp;in&nbsp;the&nbsp;market.”</h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../cribl/index.html\"><img src=\"../wp-content/uploads/2025/06/cribl-main-logo-1.png\" alt=\"Компанія Cribl\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../bitsight/index.html\"><img src=\"../wp-content/uploads/2025/05/idcga79fuc_1748615381447-1.svg\" alt=\"Компанія Bitsight\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../sonar/index.html\"><img src=\"../wp-content/uploads/2025/05/sonar_logo_light-backgrounds%404x.png\" alt=\"Компанія Sonar\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../nacview/index.html\"><img src=\"../wp-content/uploads/2025/05/nacview-logo.webp\" alt=\"Компанія NACVIEW \"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../cyber-unit-technologies/index.html\"><img src=\"../wp-content/uploads/2025/04/cyber-unit-transparent-black-105-1.png\" alt=\"Компанія Cyber Unit Technologies\"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../censys/index.html\"><img src=\"../wp-content/uploads/2025/03/cencys-for-webinar.png\" alt=\"Компанія Censys \"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../company-black-duck/index.html\"><img src=\"../wp-content/uploads/2025/02/black-duck-rozmir-dlya-sajtu-1-1.png\" alt=\"Компанія Black Duck (Synopsys) \"/></a></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"linkDestination\":\"custom\"} -->\n<figure class=\"wp-block-image\"><a class=\"marquee__item marquee-partners__item\" href=\"../sycope/index.html\"><img src=\"../wp-content/uploads/2025/02/sycope-1.png\" alt=\"Компанія Sycope \"/></a></figure>\n<!-- /wp:image -->\n\n<!--